export function getIntel(cardId: string): CardIntel {
  return INTEL[cardId] ?? EMPTY_INTEL;
}

/** Resolve a card ID to the original display name from cards.ts. */
export function getCardNameById(cardId: string): string {
  const card = CARDS.find((c) => c.id === cardId);
  return card ? card.name : cardId;
}
